  string dir=AssetDatabase.GenerateUniqueAssetPath("Assets/ChestSideUvProof");AssetDatabase.CreateFolder("Assets",Path.GetFileName(dir));string source=File.ReadAllText("Assets/MapSharedProps/Runtime/ChestMetal.shader").Replace("Shader \"MapSharedProps/ChestMetal\"","Shader \"Hidden/ChestSideUvProof\"").Replace("#include \"ChestSurface.hlsl\"","#include \"Assets/MapSharedProps/Runtime/ChestSurface.hlsl\"").Replace("return half4(rgb,1);","\n#if defined(CHEST_SURFACE)\n return half4(ChestSurfaceSampleUV(i.surface,i.positionOS).xy,0,1);\n#else\n return 0;\n#endif\n");string file=dir+"/UV.shader";File.WriteAllText(file,source);AssetDatabase.ImportAsset(file,ImportAssetOptions.ForceSynchronousImport);var shader=AssetDatabase.LoadAssetAtPath<Shader>(file);check("side UV probe compiles production function",shader&&!ShaderUtil.ShaderHasError(shader),"");
