  var oldPosition=camera.transform.position;var oldRotation=camera.transform.rotation;bool oldOrtho=camera.orthographic;float oldSize=camera.orthographicSize,oldAspect=camera.aspect,oldFov=camera.fieldOfView;var oldTarget=camera.targetTexture;var rt=new RenderTexture(64,64,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear);camera.targetTexture=rt;camera.aspect=1;camera.orthographic=true;camera.orthographicSize=.35f;camera.transform.position=new Vector3(2,.245f,0);camera.transform.rotation=Quaternion.LookRotation(Vector3.left,Vector3.up);
