   var vertices=new System.Collections.Generic.List<Vector3>();var normals=new System.Collections.Generic.List<Vector3>();var triangles=new System.Collections.Generic.List<int>();for(int y=0;y<=32;y++){float t=.15f+y/32f*1.3f;for(int x=0;x<=8;x++){vertices.Add(new Vector3(-.36f+x/8f*.72f,.435f+.274f*Mathf.Sin(t),.337f*Mathf.Cos(t)));normals.Add(new Vector3(0,Mathf.Sin(t),Mathf.Cos(t)));if(y<32&&x<8){int n=y*9+x;triangles.AddRange(new[]{n,n+10,n+1,n,n+9,n+10});}}}mesh.Clear();mesh.SetVertices(vertices);mesh.SetNormals(normals);mesh.colors=Enumerable.Repeat(Color.white,vertices.Count).ToArray();mesh.uv=Enumerable.Repeat(new Vector2(.5f,.5f),vertices.Count).ToArray();mesh.SetTriangles(triangles,0);material.SetFloat("_Cull",0);camera.orthographic=false;camera.fieldOfView=40;camera.transform.position=new Vector3(0,1.3f,2);camera.transform.LookAt(new Vector3(0,.60f,0));for(int k=0;k<3;k++)camera.Render();image.ReadPixels(new Rect(0,0,64,64),0,0);image.Apply();foreach(float u in new[]{.25f,.75f})foreach(float t in new[]{.35f,1.05f}){var point=new Vector3(-.38f+u*.76f,.435f+.274f*Mathf.Sin(t),.337f*Mathf.Cos(t));var screen=camera.WorldToViewportPoint(point);var actual=image.GetPixel((int)(screen.x*64),(int)(screen.y*64));float v=(Mathf.Atan2(point.y-.435f,point.z)/Mathf.PI-.04f)/.30f;var expected=new Vector2((1+(8+u*239)/256)*.5f,(1+(8+v*239)/256)*.5f);check("lid UV GPU curved patch "+u+","+t,Math.Abs(actual.r-expected.x)<.035f&&Math.Abs(actual.g-expected.y)<.035f,"actual="+actual+", expected="+expected);}File.WriteAllBytes(Path.Combine(output,"surface-lid-uv.png"),image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);RenderTexture.active=previous;}
